def test_send_frame_with_closing_transport(
    loop: asyncio.AbstractEventLoop,
) -> None:
    class MockTransport(asyncio.Transport):
        def is_closing(self) -> bool:
            return True

        def write(self, data: bytes) -> None:
            pass

    class MockProtocol(BaseProtocol):
        async def _drain_helper(self) -> None:
            pass

    writer = WebSocketWriter(MockProtocol(loop=loop), MockTransport())
    message = b"Hello, World!"

    with pytest.raises(ClientConnectionResetError):
        loop.run_until_complete(writer._send_frame(message, WSMsgType.TEXT))

